import{_ as t,o as s,c as n,ag as e}from"./chunks/framework.OsDJF_Ea.js";const u=JSON.parse('{"title":"봇 사용 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/bots.md","filePath":"02-user-guide/bots.md","lastUpdated":1776160579000}'),l={name:"02-user-guide/bots.md"};function d(o,a,i,p,r,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="봇-사용-가이드" tabindex="-1">봇 사용 가이드 <a class="header-anchor" href="#봇-사용-가이드" aria-label="Permalink to &quot;봇 사용 가이드&quot;">​</a></h1><p>Workhub에는 업무 자동화를 도와주는 <strong>4가지 봇</strong>이 내장되어 있습니다. 봇은 채널에서 슬래시 명령어(<code>/</code>)로 실행하거나, DM을 통해 자동으로 알림을 받을 수 있습니다.</p><hr><h2 id="봇-시작하기" tabindex="-1">봇 시작하기 <a class="header-anchor" href="#봇-시작하기" aria-label="Permalink to &quot;봇 시작하기&quot;">​</a></h2><p>봇을 처음 사용하는 분을 위한 기본 안내입니다.</p><h3 id="봇이란" tabindex="-1">봇이란? <a class="header-anchor" href="#봇이란" aria-label="Permalink to &quot;봇이란?&quot;">​</a></h3><p>봇은 채널이나 DM에서 자동으로 동작하는 <strong>자동화 도우미</strong>입니다. 사람처럼 메시지를 보내고 받지만, 정해진 규칙에 따라 자동으로 동작합니다.</p><p>봇은 세 가지 방식으로 동작합니다:</p><table tabindex="0"><thead><tr><th>유형</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><strong>자동 봇</strong></td><td>정해진 시간에 알아서 DM을 보냅니다</td><td>스탠드업 봇, 태스크 알림 봇</td></tr><tr><td><strong>명령어 봇</strong></td><td>사용자가 채널에서 <code>/명령어</code>를 입력하면 동작합니다</td><td>투표/설문 봇, 취합 봇</td></tr><tr><td><strong>@멘션 봇</strong></td><td><code>@봇이름 질문</code>으로 직접 대화합니다</td><td>검색 봇, 알림 봇</td></tr></tbody></table><h3 id="봇-메시지-구분하기" tabindex="-1">봇 메시지 구분하기 <a class="header-anchor" href="#봇-메시지-구분하기" aria-label="Permalink to &quot;봇 메시지 구분하기&quot;">​</a></h3><p>채널이나 DM에서 봇이 보낸 메시지는 일반 사용자 메시지와 구분됩니다:</p><ul><li>프로필 이름 옆에 <strong><code>봇</code></strong> 배지가 표시됩니다</li><li>봇 메시지는 자동화된 형식(표, 리스트 등)으로 정리되어 있습니다</li></ul><h3 id="채널에서-슬래시-명령어-사용하기" tabindex="-1">채널에서 슬래시 명령어 사용하기 <a class="header-anchor" href="#채널에서-슬래시-명령어-사용하기" aria-label="Permalink to &quot;채널에서 슬래시 명령어 사용하기&quot;">​</a></h3><p>투표, 설문, 취합 등의 봇은 <strong>슬래시 명령어</strong>로 실행합니다.</p><p><strong>사용 방법:</strong></p><ol><li>봇이 활성화된 <strong>채널</strong>에 들어갑니다</li><li>하단 메시지 입력창에 <code>/</code>를 입력합니다</li><li>사용 가능한 명령어 <strong>자동완성 목록</strong>이 나타납니다</li><li>원하는 명령어를 선택하거나 직접 입력합니다</li><li>명령어 뒤에 필요한 내용을 작성하고 <strong>Enter</strong>를 누릅니다</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>예시: /투표 점심 메뉴 | 한식 | 중식 | 양식</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">자동완성 활용</p><p><code>/</code>를 입력하면 현재 채널에서 사용할 수 있는 모든 명령어가 표시됩니다. 명령어 이름 일부를 추가로 입력하면 목록이 필터링됩니다.</p></div><h3 id="봇-dm-확인하기" tabindex="-1">봇 DM 확인하기 <a class="header-anchor" href="#봇-dm-확인하기" aria-label="Permalink to &quot;봇 DM 확인하기&quot;">​</a></h3><p>자동 봇(스탠드업, 태스크 알림)이나 설문/취합 봇은 **DM(다이렉트 메시지)**으로 질문을 보냅니다.</p><p><strong>DM 확인 방법:</strong></p><ol><li>왼쪽 사이드바에서 <strong>DM</strong> 메뉴를 클릭합니다</li><li>DM 목록에서 <strong>봇 이름</strong>(예: &quot;스탠드업 봇&quot;, &quot;취합 봇&quot;)을 찾습니다</li><li>읽지 않은 메시지가 있으면 <strong>알림 뱃지</strong>가 표시됩니다</li><li>봇 대화방을 클릭하여 내용을 확인합니다</li></ol><h3 id="봇에게-답변하기" tabindex="-1">봇에게 답변하기 <a class="header-anchor" href="#봇에게-답변하기" aria-label="Permalink to &quot;봇에게 답변하기&quot;">​</a></h3><p>봇이 DM으로 질문을 보내면, <strong>같은 DM 대화방에서 텍스트를 입력</strong>하면 됩니다.</p><div class="warning custom-block"><p class="custom-block-title">주의</p><ul><li>봇이 보낸 <strong>DM 대화방 안에서</strong> 답변해야 합니다 (다른 채널에서 답변하면 인식하지 못합니다)</li><li><strong>텍스트만</strong> 인식합니다 — 이미지나 파일 첨부는 답변으로 인식되지 않습니다</li></ul></div><hr><h2 id="봇-목록" tabindex="-1">봇 목록 <a class="header-anchor" href="#봇-목록" aria-label="Permalink to &quot;봇 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>봇</th><th>주요 기능</th><th>실행 방법</th></tr></thead><tbody><tr><td><a href="#데일리-스탠드업-봇">데일리 스탠드업 봇</a></td><td>매일 아침 태스크 현황 확인 + 업데이트</td><td>자동 (DM)</td></tr><tr><td><a href="#태스크-알림-봇">태스크 알림 봇</a></td><td>퇴근 전 마감일 알림 + 상태 업데이트</td><td>자동 (DM)</td></tr><tr><td><a href="#투표-설문-봇">투표/설문 봇</a></td><td>채널 투표 &amp; DM 설문</td><td>슬래시 명령어</td></tr><tr><td><a href="#취합-봇">취합 봇</a></td><td>팀원 의견/자료 취합</td><td>슬래시 명령어</td></tr></tbody></table><hr><h2 id="데일리-스탠드업-봇" tabindex="-1">데일리 스탠드업 봇 <a class="header-anchor" href="#데일리-스탠드업-봇" aria-label="Permalink to &quot;데일리 스탠드업 봇&quot;">​</a></h2><p>매일 아침 담당 태스크 목록을 보여주고, <strong>단답형 명령어</strong>로 태스크 상태를 바로 업데이트할 수 있습니다.</p><h3 id="동작-흐름" tabindex="-1">동작 흐름 <a class="header-anchor" href="#동작-흐름" aria-label="Permalink to &quot;동작 흐름&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00  담당 태스크 목록 + 명령어 안내 DM 발송</span></span>
<span class="line"><span>       ↓ 단답형 명령으로 태스크 업데이트</span></span>
<span class="line"><span>09:30  미응답자에게 리마인더 발송</span></span>
<span class="line"><span>10:00  채널에 스탠드업 리포트 게시</span></span></code></pre></div><h3 id="받게-되는-메시지" tabindex="-1">받게 되는 메시지 <a class="header-anchor" href="#받게-되는-메시지" aria-label="Permalink to &quot;받게 되는 메시지&quot;">​</a></h3><p>봇이 DM으로 담당 태스크 목록을 <strong>프로젝트 &gt; 토픽</strong> 계층으로 보여줍니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🌅 좋은 아침입니다, Kim님!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>📋 담당 태스크 3건:</span></span>
<span class="line"><span>  📁 워크허브 &gt; 프론트엔드</span></span>
<span class="line"><span>    🔵 1. 로그인 페이지 리디자인 [긴급] (D-1)</span></span>
<span class="line"><span>    ⬜ 2. 대시보드 차트 컴포넌트 [보통] (D-5)</span></span>
<span class="line"><span>  📁 워크허브 &gt; 백엔드</span></span>
<span class="line"><span>    🔵 3. API 리팩토링 [낮음] (D-10)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>──────────────</span></span>
<span class="line"><span>태스크 상태를 업데이트해 주세요:</span></span>
<span class="line"><span>  완료 → &quot;1완료&quot;  진행 → &quot;2진행&quot;</span></span>
<span class="line"><span>  블록 → &quot;3블록 사유&quot;  연장 → &quot;1연장&quot;</span></span>
<span class="line"><span>  여러개 → &quot;1완료 2진행&quot;</span></span>
<span class="line"><span>  건너뛰기 → &quot;다음&quot;</span></span></code></pre></div><h3 id="단답형-명령어" tabindex="-1">단답형 명령어 <a class="header-anchor" href="#단답형-명령어" aria-label="Permalink to &quot;단답형 명령어&quot;">​</a></h3><table tabindex="0"><thead><tr><th>명령어</th><th>동작</th><th>예시</th></tr></thead><tbody><tr><td><code>N완료</code></td><td>태스크를 <strong>완료</strong> 처리</td><td><code>1완료</code></td></tr><tr><td><code>N진행</code></td><td>태스크를 <strong>진행 중</strong> 상태로 변경</td><td><code>2진행</code></td></tr><tr><td><code>N블록 사유</code></td><td>태스크를 <strong>블로커</strong> 상태로 변경 + 사유 기록</td><td><code>3블록 API 미확정</code></td></tr><tr><td><code>N연장</code></td><td>마감일을 <strong>+3일</strong> 연장</td><td><code>1연장</code></td></tr><tr><td><code>다음</code></td><td>태스크 업데이트를 건너뛰기</td><td><code>다음</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">여러 태스크 한 번에 처리</p><p>공백으로 구분하여 한 줄로 여러 태스크를 처리할 수 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1완료 2진행 3블록 API스펙 미확정</span></span></code></pre></div></div><h3 id="새-태스크-생성" tabindex="-1">새 태스크 생성 <a class="header-anchor" href="#새-태스크-생성" aria-label="Permalink to &quot;새 태스크 생성&quot;">​</a></h3><p>태스크 업데이트 후 오늘 할 새 업무를 등록할 수 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>봇: 오늘 새로 할 일이 있나요?</span></span>
<span class="line"><span>    &quot;생성 태스크제목&quot; 또는 &quot;없음&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>나: 생성 사용자 프로필 페이지</span></span>
<span class="line"><span></span></span>
<span class="line"><span>봇: 📁 어디에 생성할까요?</span></span>
<span class="line"><span>      1. 워크허브 &gt; 프론트엔드</span></span>
<span class="line"><span>      2. 워크허브 &gt; 백엔드</span></span>
<span class="line"><span></span></span>
<span class="line"><span>나: 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>봇: ✅ &quot;사용자 프로필 페이지&quot; 생성 완료!</span></span></code></pre></div><h3 id="스탠드업-리포트" tabindex="-1">스탠드업 리포트 <a class="header-anchor" href="#스탠드업-리포트" aria-label="Permalink to &quot;스탠드업 리포트&quot;">​</a></h3><p>10:00에 채널에 자동으로 게시되는 리포트에는 다음이 포함됩니다:</p><ul><li>각 팀원의 태스크 업데이트 내역 (완료/진행/블로커)</li><li>새로 생성한 태스크 목록</li><li>블로커가 있는 경우 별도 표시</li><li>응답률 통계</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>담당 태스크가 없으면 바로 새 태스크 생성 단계로 넘어갑니다.</p></div><hr><h2 id="태스크-알림-봇" tabindex="-1">태스크 알림 봇 <a class="header-anchor" href="#태스크-알림-봇" aria-label="Permalink to &quot;태스크 알림 봇&quot;">​</a></h2><p>퇴근 전에 마감 임박/초과 태스크를 <strong>프로젝트 &gt; 토픽</strong> 계층으로 정리하여 DM으로 보내줍니다. 번호를 선택하여 개별 태스크를 처리할 수 있습니다.</p><h3 id="동작-흐름-1" tabindex="-1">동작 흐름 <a class="header-anchor" href="#동작-흐름-1" aria-label="Permalink to &quot;동작 흐름&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>17:00  마감 임박/초과 태스크 스캔 → 담당자에게 DM 알림</span></span>
<span class="line"><span>       ↓ 번호 선택 → 상태 업데이트</span></span>
<span class="line"><span>17:30  채널에 일일 태스크 리포트 게시</span></span></code></pre></div><h3 id="알림-시점" tabindex="-1">알림 시점 <a class="header-anchor" href="#알림-시점" aria-label="Permalink to &quot;알림 시점&quot;">​</a></h3><table tabindex="0"><thead><tr><th>시점</th><th>알림 내용</th></tr></thead><tbody><tr><td><strong>D-3</strong></td><td>마감 3일 전 — 사전 알림</td></tr><tr><td><strong>D-1</strong></td><td>마감 1일 전 — 긴급 알림</td></tr><tr><td><strong>D-Day</strong></td><td>마감일 당일</td></tr><tr><td><strong>D+1</strong></td><td>마감 1일 초과 — 지연 경고</td></tr><tr><td><strong>D+3</strong></td><td>마감 3일 초과 — 에스컬레이션</td></tr></tbody></table><h3 id="dm-알림-예시" tabindex="-1">DM 알림 예시 <a class="header-anchor" href="#dm-알림-예시" aria-label="Permalink to &quot;DM 알림 예시&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔔 태스크 마감 알림 — 3건</span></span>
<span class="line"><span></span></span>
<span class="line"><span>📁 워크허브 &gt; 프론트엔드</span></span>
<span class="line"><span>  🚨 1. 로그인 리디자인 [긴급] (마감: 04-08, 2일 초과)</span></span>
<span class="line"><span>  🔥 2. 대시보드 차트 [보통] (마감: 04-10, D-Day)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>📁 워크허브 &gt; 백엔드</span></span>
<span class="line"><span>  🔔 3. API 리팩토링 [낮음] (마감: 04-13, D-3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>──────────────</span></span>
<span class="line"><span>번호를 입력하여 태스크를 선택하세요 (예: 1)</span></span>
<span class="line"><span>&quot;전체완료&quot; — 모든 태스크를 완료 처리</span></span>
<span class="line"><span>&quot;0&quot; — 종료</span></span></code></pre></div><h3 id="답변-방법" tabindex="-1">답변 방법 <a class="header-anchor" href="#답변-방법" aria-label="Permalink to &quot;답변 방법&quot;">​</a></h3><p><strong>Step 1 — 태스크 선택:</strong></p><p>번호를 입력하면 해당 태스크의 상세 정보와 액션 메뉴가 표시됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>나: 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>봇: 🚨 로그인 리디자인 [긴급]</span></span>
<span class="line"><span>    📁 워크허브 &gt; 프론트엔드 | 📅 04-08 (D+2)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    1️⃣ 완료했어요 → &quot;done&quot;으로 변경</span></span>
<span class="line"><span>    2️⃣ 진행 중이에요 → 상태 유지</span></span>
<span class="line"><span>    3️⃣ 마감 연장 필요 → 연장 요청</span></span>
<span class="line"><span>    0️⃣ 돌아가기</span></span></code></pre></div><p><strong>Step 2 — 액션 선택:</strong></p><table tabindex="0"><thead><tr><th>답변</th><th>동작</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>태스크를 &quot;완료&quot;로 변경 (완료일 자동 기록)</td></tr><tr><td><strong>2</strong></td><td>&quot;진행 중&quot; 상태 유지</td></tr><tr><td><strong>3</strong></td><td>마감 +3일 연장 (사유 입력 → 관리자 보고)</td></tr><tr><td><strong>0</strong></td><td>목록으로 돌아가기</td></tr></tbody></table><p><strong>처리 후:</strong> 남은 태스크가 있으면 재번호가 부여된 목록이 다시 표시됩니다. 모든 태스크를 처리하면 세션이 종료됩니다.</p><div class="tip custom-block"><p class="custom-block-title">전체완료</p><p>태스크가 모두 끝났다면 <code>전체완료</code>를 입력하여 한 번에 모두 완료 처리할 수 있습니다.</p></div><h3 id="일일-태스크-리포트" tabindex="-1">일일 태스크 리포트 <a class="header-anchor" href="#일일-태스크-리포트" aria-label="Permalink to &quot;일일 태스크 리포트&quot;">​</a></h3><p>매일 17:30에 지정된 채널에 자동으로 리포트가 게시됩니다:</p><ul><li>마감 초과 태스크 목록 (프로젝트 &gt; 토픽 표시)</li><li>오늘 마감 태스크 목록</li><li>마감 임박 태스크 목록</li><li>각 담당자별 현황</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>태스크에 마감일을 설정해야 알림을 받을 수 있습니다. 칸반 보드에서 태스크를 편집하여 마감일을 지정하세요.</p></div><hr><h2 id="투표-설문-봇" tabindex="-1">투표/설문 봇 <a class="header-anchor" href="#투표-설문-봇" aria-label="Permalink to &quot;투표/설문 봇&quot;">​</a></h2><p>채널에서 실시간 투표를 진행하거나, DM 기반의 설문조사를 실행할 수 있습니다.</p><h3 id="투표-만들기" tabindex="-1">투표 만들기 <a class="header-anchor" href="#투표-만들기" aria-label="Permalink to &quot;투표 만들기&quot;">​</a></h3><p>채널 메시지 입력창에서 슬래시 명령어를 입력합니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/투표 제목 | 항목1 | 항목2 | 항목3</span></span></code></pre></div><h4 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h4><table tabindex="0"><thead><tr><th>옵션</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><code>--익명</code></td><td>익명 투표 (누가 투표했는지 비공개)</td><td>\`/투표 점심 메뉴</td></tr><tr><td><code>--복수</code></td><td>복수 선택 허용</td><td>\`/투표 회식 날짜</td></tr><tr><td><code>--시간 30분</code></td><td>제한 시간 설정 (기본: 60분)</td><td>\`/투표 긴급 안건</td></tr></tbody></table><h4 id="예시" tabindex="-1">예시 <a class="header-anchor" href="#예시" aria-label="Permalink to &quot;예시&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/투표 이번 주 회식 장소 | 고깃집 | 횟집 | 이탈리안 | 중식당 --복수 --시간 120분</span></span></code></pre></div><h3 id="투표-참여-방법" tabindex="-1">투표 참여 방법 <a class="header-anchor" href="#투표-참여-방법" aria-label="Permalink to &quot;투표 참여 방법&quot;">​</a></h3><ol><li>봇이 채널에 투표 카드를 게시합니다</li><li><strong>번호를 입력</strong>하여 투표합니다 (예: <code>1</code>, <code>2</code>, <code>3</code>)</li><li>복수 선택이 허용된 경우 쉼표로 구분합니다 (예: <code>1,3</code>)</li><li>5표마다 중간 결과가 자동으로 표시됩니다</li><li>제한 시간이 지나면 최종 결과가 게시됩니다</li></ol><h3 id="설문조사-만들기" tabindex="-1">설문조사 만들기 <a class="header-anchor" href="#설문조사-만들기" aria-label="Permalink to &quot;설문조사 만들기&quot;">​</a></h3><p>DM 기반의 다중 질문 설문을 실행합니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/설문 분기 만족도 조사</span></span></code></pre></div><h4 id="옵션-1" tabindex="-1">옵션 <a class="header-anchor" href="#옵션-1" aria-label="Permalink to &quot;옵션&quot;">​</a></h4><table tabindex="0"><thead><tr><th>옵션</th><th>설명</th></tr></thead><tbody><tr><td><code>--익명</code></td><td>익명 설문</td></tr></tbody></table><h3 id="설문-참여-방법" tabindex="-1">설문 참여 방법 <a class="header-anchor" href="#설문-참여-방법" aria-label="Permalink to &quot;설문 참여 방법&quot;">​</a></h3><ol><li><code>/설문</code> 명령을 실행하면 채널 구성원에게 DM이 발송됩니다</li><li>봇 DM에서 질문에 하나씩 답변합니다</li><li>텍스트 답변 또는 점수(1~5) 평가를 합니다</li><li>모든 응답이 수집되면 채널에 결과 리포트가 게시됩니다</li></ol><h3 id="설문-결과-리포트" tabindex="-1">설문 결과 리포트 <a class="header-anchor" href="#설문-결과-리포트" aria-label="Permalink to &quot;설문 결과 리포트&quot;">​</a></h3><ul><li>텍스트 응답: 주요 키워드 분석</li><li>점수 응답: 평균 점수 계산</li><li>응답률 표시</li></ul><hr><h2 id="취합-봇" tabindex="-1">취합 봇 <a class="header-anchor" href="#취합-봇" aria-label="Permalink to &quot;취합 봇&quot;">​</a></h2><p>팀원들에게 DM으로 자료나 의견을 요청하고, 마감일에 자동으로 결과를 모아 채널에 게시합니다.</p><h3 id="취합-요청-만들기" tabindex="-1">취합 요청 만들기 <a class="header-anchor" href="#취합-요청-만들기" aria-label="Permalink to &quot;취합 요청 만들기&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/취합 제목 | 마감: 날짜 | 항목: 항목1, 항목2</span></span></code></pre></div><h4 id="예시-1" tabindex="-1">예시 <a class="header-anchor" href="#예시-1" aria-label="Permalink to &quot;예시&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/취합 주간 업무 보고 | 마감: 2026-04-11 | 항목: 이번주 성과, 다음주 계획, 이슈사항(선택)</span></span></code></pre></div><ul><li><strong>제목</strong>: 취합 주제</li><li><strong>마감</strong>: 마감일 (YYYY-MM-DD 형식)</li><li><strong>항목</strong>: 수집할 항목 목록 (쉼표 구분)</li><li>항목 뒤에 <code>(선택)</code>을 붙이면 선택 항목이 됩니다</li></ul><h3 id="응답-방법" tabindex="-1">응답 방법 <a class="header-anchor" href="#응답-방법" aria-label="Permalink to &quot;응답 방법&quot;">​</a></h3><ol><li>봇이 채널 구성원에게 DM으로 취합 요청을 보냅니다</li><li>각 항목에 대해 <strong>순서대로 텍스트로 답변</strong>합니다</li><li>답변 완료 전에 <strong>검토 및 수정</strong>할 수 있습니다</li><li>최종 제출 후 요청자에게 알림이 갑니다</li></ol><h3 id="진행-상황-확인" tabindex="-1">진행 상황 확인 <a class="header-anchor" href="#진행-상황-확인" aria-label="Permalink to &quot;진행 상황 확인&quot;">​</a></h3><p>취합을 요청한 사람은 진행 상황을 확인할 수 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/취합현황</span></span></code></pre></div><ul><li>응답 완료/미응답 인원 확인</li><li>실시간 응답률 표시</li></ul><h3 id="리마인더" tabindex="-1">리마인더 <a class="header-anchor" href="#리마인더" aria-label="Permalink to &quot;리마인더&quot;">​</a></h3><ul><li>매일 오전 9시에 미제출자에게 자동으로 리마인더가 발송됩니다</li><li>마감일에 자동으로 결과 보고서가 채널에 게시됩니다</li></ul><h3 id="결과-보고서" tabindex="-1">결과 보고서 <a class="header-anchor" href="#결과-보고서" aria-label="Permalink to &quot;결과 보고서&quot;">​</a></h3><p>마감 시 채널에 자동으로 게시되는 보고서에 포함되는 내용:</p><ul><li>응답률 (제출/전체)</li><li>각 팀원의 항목별 응답 내용</li><li>미응답자 목록</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>선택 항목은 응답하지 않아도 제출이 가능합니다. 필수 항목은 반드시 답변해야 합니다.</p></div><hr><h2 id="멘션으로-봇-호출하기" tabindex="-1">@멘션으로 봇 호출하기 <a class="header-anchor" href="#멘션으로-봇-호출하기" aria-label="Permalink to &quot;@멘션으로 봇 호출하기&quot;">​</a></h2><p>슬래시 명령어 외에도 <code>@봇이름</code>으로 봇을 호출할 수 있습니다. 채널, 프로젝트 토픽, DM 어디에서든 사용 가능합니다.</p><h3 id="사용-방법" tabindex="-1">사용 방법 <a class="header-anchor" href="#사용-방법" aria-label="Permalink to &quot;사용 방법&quot;">​</a></h3><ol><li>메시지 입력창에서 <code>@</code>를 입력합니다</li><li>멘션 목록에서 <strong>봇</strong> 섹션의 봇을 선택합니다</li><li>봇 이름 뒤에 질문이나 요청 내용을 작성합니다</li><li>Enter를 누르면 봇이 쓰레드(답글)로 응답합니다</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@검색봇 이번 달 회의록 찾아줘</span></span>
<span class="line"><span>@알림봇 내 마감 임박 태스크 알려줘</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>멘션 목록은 <strong>사람</strong>, <strong>조직</strong>, <strong>봇</strong> 세 그룹으로 구분되어 표시됩니다. 봇은 이름 옆에 <strong>봇</strong> 배지가 붙어 있어 쉽게 구분할 수 있습니다.</p></div><hr><h2 id="슬래시-명령어-요약" tabindex="-1">슬래시 명령어 요약 <a class="header-anchor" href="#슬래시-명령어-요약" aria-label="Permalink to &quot;슬래시 명령어 요약&quot;">​</a></h2><table tabindex="0"><thead><tr><th>명령어</th><th>봇</th><th>설명</th></tr></thead><tbody><tr><td><code>/요약</code></td><td>AI 봇</td><td>최근 메시지 요약 (DM 전달)</td></tr><tr><td><code>/회의록</code></td><td>AI 봇</td><td>회의록 정리 (DM 전달)</td></tr><tr><td><code>/번역 텍스트</code></td><td>AI 봇</td><td>텍스트 번역</td></tr><tr><td><code>/도움말</code></td><td>시스템</td><td>명령어 목록 안내</td></tr><tr><td><code>/투표 제목 | 항목1 | 항목2</code></td><td>투표/설문 봇</td><td>채널 투표 생성</td></tr><tr><td><code>/설문 제목</code></td><td>투표/설문 봇</td><td>DM 설문조사 생성</td></tr><tr><td><code>/취합 제목 | 마감: 날짜 | 항목: ...</code></td><td>취합 봇</td><td>자료 취합 요청</td></tr><tr><td><code>/취합현황</code></td><td>취합 봇</td><td>취합 진행 상황 확인</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>슬래시 명령어는 채널 메시지 입력창에서 <code>/</code>를 입력하면 자동완성 목록이 표시됩니다. AI 명령어에 대한 자세한 내용은 <a href="/docs/02-user-guide/ai-commands.html">AI 슬래시 명령어</a> 페이지를 참고하세요.</p></div><hr><h2 id="봇에게-답변하는-팁" tabindex="-1">봇에게 답변하는 팁 <a class="header-anchor" href="#봇에게-답변하는-팁" aria-label="Permalink to &quot;봇에게 답변하는 팁&quot;">​</a></h2><ol><li><strong>DM에서 답변</strong> — 봇이 보낸 DM 대화방에서 바로 텍스트를 입력하면 됩니다</li><li><strong>단답형 명령</strong> — 스탠드업 봇은 <code>1완료 2진행</code> 같은 단답형 명령을 사용합니다</li><li><strong>번호 선택</strong> — 태스크 알림 봇은 번호로 태스크를 선택하고 액션을 고릅니다</li><li><strong>한 줄 일괄 처리</strong> — 스탠드업에서 여러 태스크를 한 줄로 처리할 수 있습니다</li></ol><div class="warning custom-block"><p class="custom-block-title">주의사항</p><ul><li>봇은 <strong>텍스트 메시지만</strong> 인식합니다 (이미지, 파일은 인식하지 않음)</li><li>봇의 응답 데이터는 메모리에 저장되므로, <strong>서버 재시작 시 진행 중인 세션이 초기화</strong>될 수 있습니다</li><li>봇 관련 문제가 발생하면 기관관리자에게 문의하세요</li></ul></div>`,123)])])}const b=t(l,[["render",d]]);export{u as __pageData,b as default};
